{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly states that 'WAL works best with smaller transactions.'",
      "citations": [
        {
          "index": 0,
          "quote": "WAL works best with smaller transactions."
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [0] states that traditional rollback journal modes will likely be faster for transactions larger than about 100 megabytes, not 10 megabytes. Additionally, it notes that beginning with version 3.11.0, WAL mode works as efficiently with large transactions as does rollback mode.",
      "citations": [
        {
          "index": 0,
          "quote": "For transactions larger than about 100 megabytes, traditional rollback journal modes will likely be faster."
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly mentions that for transactions in excess of a gigabyte, WAL mode may fail with an I/O or disk-full error.",
      "citations": [
        {
          "index": 0,
          "quote": "For transactions in excess of a gigabyte, WAL mode may fail with an I/O or disk-full error."
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] states that WAL might be very slightly slower (perhaps 1% or 2% slower) than the traditional rollback-journal approach in applications that do mostly reads and seldom write.",
      "citations": [
        {
          "index": 1,
          "quote": "WAL might be very slightly slower (perhaps 1% or 2% slower) than the traditional rollback-journal approach in applications that do mostly reads and seldom write."
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] explains that write transactions are very fast because they only involve writing the content once.",
      "citations": [
        {
          "index": 2,
          "quote": "Write transactions are very fast since they only involve writing the content once"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_id": "c1",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly states that a checkpoint can run concurrently with readers.",
      "citations": [
        {
          "index": 0,
          "quote": "A checkpoint can run concurrently with readers"
        }
      ]
    },
    {
      "claim_id": "c2",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] states that the checkpoint must stop when it reaches a page in the WAL past the end mark of any current reader to avoid overwriting data being used by the reader.",
      "citations": [
        {
          "index": 0,
          "quote": "however the checkpoint must stop when it reaches a page in the WAL that is past the end mark of any current reader."
        }
      ]
    },
    {
      "claim_id": "c3",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] directly states that a long-running read transaction can prevent a checkpointer from making progress.",
      "citations": [
        {
          "index": 1,
          "quote": "Thus a long-running read transaction can prevent a checkpointer from making progress."
        }
      ]
    },
    {
      "claim_id": "c4",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [3] states that if there is always at least one active reader, no checkpoints will be able to complete, causing the WAL file to grow without bound. This contradicts the claim that they still complete (even slowly).",
      "citations": [
        {
          "index": 3,
          "quote": "if a database has many concurrent overlapping readers and there is always at least one active reader, then no checkpoints will be able to complete"
        }
      ]
    },
    {
      "claim_id": "c5",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [4] states that the disadvantage of using SQLITE_CHECKPOINT_RESTART is that readers might block while the checkpoint is running. The claim says it guarantees readers are never blocked, which is false.",
      "citations": [
        {
          "index": 4,
          "quote": "The disadvantage of using SQLITE_CHECKPOINT_RESTART and SQLITE_CHECKPOINT_TRUNCATE is that readers might block while the checkpoint is running."
        }
      ]
    },
    {
      "claim_id": "c6",
      "verdict": "UNSUPPORTED",
      "reasoning": "While Passage [3] discusses how continuous readers cause WAL growth, none of the passages state that this is the 'most common' cause in production systems. That is an external statistical claim not found in the text.",
      "citations": []
    }
  ]
}

